import sys
from contextlib import redirect_stdout

def solve(text):
    def program():
        N = int(input())
        P = list(map(int, input().split()))
        # flg[a][b] == True means "a beats b" (i.e., output should be a)
        # Build from the permutation P: P is a ranking order from best to worst.
        # If position of a is earlier than position of b, then a beats b.
        pos = [0] * (N + 1)
        for idx, val in enumerate(P):
            pos[val] = idx

        flg = [[False] * N for _ in range(N)]
        for a in range(1, N + 1):
            for b in range(1, N + 1):
                if a != b and pos[a] < pos[b]:
                    flg[a - 1][b - 1] = True

        Q = int(input())
        for _ in range(Q):
            A, B = map(int, input().split())
            if flg[A - 1][B - 1]:
                print(A)
            else:
                print(B)

    previous = sys.stdin
    output = io.StringIO()
    try:
        sys.stdin = io.StringIO(text)
        with redirect_stdout(output):
            program()
    except SystemExit as status:
        if status.code not in (None, 0):
            raise
    finally:
        sys.stdin = previous
    return output.getvalue().strip()

