def solve(text):
    def program():
        n = int(input().strip())
        # Start with a 1x1 block
        carp = [['#']]
        for k in range(1, n + 1):
            prev = carp[k - 1]
            size_prev = len(prev)  # 3^(k-1)
            size = size_prev * 3    # 3^k

            # Build 3x3 tiling of the previous pattern
            tmp = []
            for _ in range(3):
                for row in prev:
                    tmp.append(row * 3)

            # Carve the central square (the "hole") at this scale
            # Central block indices: [size//3, 2*size//3)
            start = size // 3
            end = 2 * size // 3
            for i in range(start, end):
                for j in range(start, end):
                    tmp[i][j] = '.'

            carp.append(tmp)

        for c in carp[n]:
            print(*c)

    previous = sys.stdin
    output = io.StringIO()
    try:
        sys.stdin = io.StringIO(text)
        with redirect_stdout(output):
            program()
    except SystemExit as status:
        if status.code not in (None, 0):
            raise
    finally:
        sys.stdin = previous
    return output.getvalue().strip()

