def solve(text):
    def program():
        from collections import Counter
        from functools import reduce

        N = int(input())

        def prime_factorize(n):
            a = []
            while n % 2 == 0:
                a.append(2)
                n //= 2
            f = 3
            while f * f <= n:
                if n % f == 0:
                    a.append(f)
                    n //= f
                else:
                    f += 2
            if n != 1:
                a.append(n)
            return a

        def num_divisors(n):
            if n == 1:
                return 1
            c = Counter(prime_factorize(n))
            # number of divisors = product (exp+1)
            return reduce(lambda x, y: x * (y + 1), c.values(), 1)

        cnt = 0
        # Iterate AB from 1..N-1, but handle symmetry correctly.
        for AB in range(1, N):
            CD = N - AB
            cntAB = 1 if AB == 1 else num_divisors(AB)
            cntCD = 1 if CD == 1 else num_divisors(CD)

            # For ordered pairs (a,b) with a*b? (as implied by original logic),
            # count both (AB,CD) and (CD,AB) when AB != CD.
            if AB != CD:
                cnt += cntAB * cntCD * 2
            else:
                cnt += cntAB * cntCD

