import sys
from contextlib import redirect_stdout

def solve(text):
    def program():
        S = input().strip()

        # Stack of sets: each '(' starts a new scope.
        stack = [set()]
        for ch in S:
            if ch.isalpha():
                # If the letter already exists in the current scope, it's invalid.
                if ch in stack[-1]:
                    print("No")
                    return
                stack[-1].add(ch)
            elif ch == '(':
                stack.append(set())
            elif ch == ')':
                # Close current scope: merge its letters into the parent scope.
                if len(stack) == 1:
                    print("No")
                    return
                finished = stack.pop()
                stack[-1].update(finished)
            else:
                # Ignore any unexpected characters (e.g., whitespace)
                continue

        # If parentheses were balanced, it's valid.
        if len(stack) != 1:
            print("No")
        else:
            print("Yes")

    previous = sys.stdin
    output = io.StringIO()
    try:
        sys.stdin = io.StringIO(text)
        with redirect_stdout(output):
            program()
    finally:
        sys.stdin = previous
    return output.getvalue().strip()

