    def program():
        A, M, L, R = map(int, input().split())

        # Count integers x such that:
        #   L <= A + M*x <= R
        # i.e. (L-A)/M <= x <= (R-A)/M
        # Works for any integer M (including negative) by using floor/ceil properly.
        def floor_div(a, b):
            # floor(a/b) for integers, with b != 0
            return a // b

        def ceil_div(a, b):
            # ceil(a/b) for integers, with b != 0
