import io
import sys
from contextlib import redirect_stdout

def solve(text):
    def program():
        n, t, l = map(int, input().split())
        # mat[i][j] = earliest step (1..t) when edge i->j becomes available,
        # or t+1 if never within first t steps.
        mat = [[t + 1] * n for _ in range(n)]
        for i in range(1, t + 1):
            u, v = map(int, input().split())
            mat[u - 1][v - 1] = i

        def mul(A, B):
            # Min-max composition:
            # (A ⊗ B)[i][k] = min_j max(A[i][j], B[j][k])
            res = [[t + 1] * n for _ in range(n)]
            for i in range(n):
                for j in range(n):
                    a = A[i][j]
                    if a == t + 1:
                        continue
                    rowB = B[j]
                    for k in range(n):
                        v = rowB[k]
                        if v == t + 1:
                            continue
                        cand = a if a > v else v  # max(a, v)
                        if cand < res[i][k]:
                            res[i][k] = cand
            return res

        def mat_pow(M, k):
            # Identity for this semiring: 0 on diagonal (no time needed),
            # t+1 elsewhere (impossible).
            res = [[t + 1] * n for _ in range(n)]
            for i in range(n):
                res[i][i] = 0
            while k:
                if k & 1:
                    res = mul(res, M)
                M = mul(M, M)
                k >>= 1
            return res

        res = mat_pow(mat, l)[0]
        for i in range(n):
            if res[i] > t:
                res[i] = -1
        print(*res)

    previous = sys.stdin
    output = io.StringIO()
    try:
        sys.stdin = io.StringIO(text)
        with redirect_stdout(output):
            program()
    except SystemExit as status:
        if status.code not in (None, 0):
            raise
    finally:
        sys.stdin = previous
    return output.getvalue

